import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Resources: a Manage pop-up per person (name, merge a duplicate, left the company), the features that then need a new owner are flagged on the roadmap and the Dashboard."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
def manage(P,name): P.locator('button[data-manage="%s"]'%name).click(); P.wait_for_timeout(300)
with sync_playwright() as pw:
    br=pw.chromium.launch(); ctx=mkctx(br); ctx.clock.set_fixed_time("2026-10-20T10:00:00"); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    A.click('#nav button[data-p="resources"]'); A.wait_for_timeout(900)
    ok('M1 every person has a Manage button', A.locator('button[data-manage]').count()>=10)
    manage(A,'Shady Bassily')
    ok('M2 the pop-up has name, merge and left-the-company parts', A.locator('#pmname').count()==1 and A.locator('#pmmerge').count()==1 and A.locator('#pmleft').count()==1)
    A.fill('#pmname','Shady B'); A.click('#pmsave'); A.wait_for_timeout(700)
    ok('M3 renaming from the pop-up renames the person', A.locator('button[data-manage="Shady B"]').count()==1 and A.locator('button[data-manage="Shady Bassily"]').count()==0)
    manage(A,'Shady B'); A.select_option('#pmmerge','Mohamed Altramsi'); A.click('#pmdo'); A.wait_for_timeout(300)
    ok('M4 merging asks first and names both people', 'Merge Shady B into Mohamed Altramsi' in A.locator('#xdlg').inner_text())
    A.click('#xdlg button:text-is("Merge")'); A.wait_for_timeout(900)
    ok('M5 after the merge the duplicate is gone and the other stays', A.locator('button[data-manage="Shady B"]').count()==0 and A.locator('button[data-manage="Mohamed Altramsi"]').count()==1)
    manage(A,'Asmaa'); A.fill('#pmleft','2026-10-25'); A.click('#pmleave'); A.wait_for_timeout(600)
    ok('M6 marking someone as leaving lists the features that run after the last day', A.locator('#pmwork').count()==1 and 'need a new owner' in A.locator('#pmwork').inner_text())
    A.click('#xdlg button:text-is("Close")'); A.wait_for_timeout(300)
    ok('M7 the Resources row shows "Leaving" with the number of features to plan', 'Leaving' in A.locator('.pmtag[data-left="Asmaa"]').inner_text() and 'to plan' in A.locator('.pmtag[data-left="Asmaa"]').inner_text())
    A.click('#nav button[data-p="capacity"]'); A.wait_for_timeout(700)
    ok('M8 the Dashboard says what needs a new owner, with a button to plan them', A.locator('button.cpplan[data-name="Asmaa"]').count()==1 and 'needs a new owner' in A.locator('#cp-fix').inner_text() or 'need a new owner' in A.locator('#cp-fix').inner_text())
    A.locator('button.cpplan[data-name="Asmaa"]').click(); A.wait_for_timeout(1200)
    ok('M9 Plan opens the roadmap on that person', A.locator('#pg-roadmap:visible').count()==1)
    ok('M10 their bars after the last day are marked on the Gantt chart', A.locator('.bar.ownerleft').count()>=1)
    A.click('#nav button[data-p="resources"]'); A.wait_for_timeout(700); manage(A,'Asmaa'); A.click('#pmclear'); A.wait_for_timeout(500); A.click('#xdlg button:text-is("Close")'); A.wait_for_timeout(300)
    ok('M11 Back in the team removes the tag', A.locator('.pmtag[data-left="Asmaa"]').count()==0)
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(800)
    c=A.locator('.mdcol[data-mo="2026-11"]'); c.locator('.mdopen').click(); ta=c.locator('.mdadd textarea'); ta.fill('Rename card'); ta.press('Enter'); A.wait_for_timeout(500); A.keyboard.press('Escape'); A.wait_for_timeout(300)
    A.locator('.mdcard:has-text("Rename card") .kebab').click(); A.locator('#ctx .mi:has-text("Points and people")').click(); A.wait_for_timeout(300)
    A.click('#xdlg .ptrack[data-k="ai"]'); r=A.locator('#xdlg .pperson[data-track="ai"][data-name="Aliaa Ibrahim"]'); r.locator('input[type=checkbox]').check(); r.locator('select').select_option('5'); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(600)
    A.click('#nav button[data-p="resources"]'); A.wait_for_timeout(700); manage(A,'Aliaa Ibrahim'); A.fill('#pmname','Aliaa K'); A.click('#pmsave'); A.wait_for_timeout(900)
    who=A.evaluate("()=>{const d=JSON.parse(localStorage.getItem('fk3')).reports.mo202611; return JSON.stringify(d.lines.find(l=>l.t==='Rename card').who)}")
    hist=A.evaluate("()=>Object.keys(JSON.parse(localStorage.getItem('fk3')).reports).filter(k=>k.startsWith('mohist'))")
    ok('M12 renaming a person also renames them on the cards, and keeps a version of the month first', '"Aliaa K":5' in who and 'Aliaa Ibrahim"' not in who and len(hist)>=1)
    ok('no page errors', errs==[]); print('errors:',errs[:3]); print(sum(1 for _,c in R if c),'/',len(R)); br.close()
